// Propuesta para revisión jurídica y validación operativa antes de publicar.
const rutaGenTermsVersion = '0.5';
// SHA-256 del archivo inmutable backend/src/modules/legal/terms/0.5.json.
const rutaGenTermsDocumentSha256 =
    'ad99f048a6cb9fc61c36970fac5185dd2f9b3ef35c641f0a3c6ea6b9b5400f61';
const rutaGenTermsUpdatedAt = '21/10/2026';

class TermsSectionData {
  const TermsSectionData({required this.number, required this.title, required this.content});
  final String number;
  final String title;
  final String content;
}

const rutaGenTermsSections = <TermsSectionData>[
  TermsSectionData(number: "1", title: "Pago con App YPF para acreditar cargas", content: "Para que una carga de combustible sea elegible para acreditar puntos y obtener los beneficios de Ruta GEN asociados a esa carga, debe abonarse a través de App YPF en una estación participante. Las cargas abonadas por otros medios no cumplen esta condición de acreditación del programa.\n\nPagar con App YPF no acredita puntos automáticamente: la operación también debe identificarse y registrarse en Ruta GEN, corresponder al titular de la cuenta y cumplir las condiciones de verificación, mínimos, equivalencias y promociones vigentes informadas antes de la carga. Una misma carga no puede acreditarse más de una vez.\n\nEste requisito corresponde a la acreditación de cargas y sus beneficios asociados. No es necesario efectuar un pago para crear una cuenta, consultar la aplicación o participar por las vías gratuitas sin obligación de compra que deban prever las bases particulares de los sorteos.\n\nApp YPF es un servicio de su propio prestador, sujeto a sus términos y condiciones. Su utilización como medio de pago no convierte a Ruta GEN en una aplicación oficial de YPF ni confunde los puntos de Ruta GEN con los de otros programas."),
  TermsSectionData(number: "2", title: "Independencia de YPF y atención de reclamos", content: "Ruta GEN es un programa independiente bajo la titularidad y responsabilidad de MAZARA GEN S.A. YPF S.A. no es titular, desarrollador, administrador, organizador ni patrocinador de Ruta GEN, sus puntos, canjes, regalos, sorteos o promociones propias. El uso de App YPF como medio de pago y la participación de estaciones de bandera YPF no implican que YPF organice, garantice o administre este programa.\n\nLas consultas y los reclamos por el funcionamiento de Ruta GEN, la acreditación o corrección de puntos, cargas registradas en el programa, canjes, beneficios y entrega de premios deben dirigirse a MAZARA GEN S.A., a mazara@grupogen.com.ar. YPF no es el canal de atención del programa Ruta GEN. El soporte técnico de la aplicación se brinda en lbcodeworks@gmail.com, sin desplazar la responsabilidad de Mazara frente al usuario.\n\nLas incidencias correspondientes al servicio de pago de App YPF deben gestionarse ante su prestador por los canales de esa aplicación; esta aclaración no atribuye a Mazara la operación de dicho servicio.\n\nEsta delimitación se refiere a la administración del programa Ruta GEN. No constituye una renuncia a derechos del consumidor ni excluye las responsabilidades que la legislación aplicable pudiera atribuir a cada interviniente por su propia actuación."),
  TermsSectionData(number: "3", title: "Titular de la aplicación y responsable del programa", content: "Ruta GEN es un programa de fidelización para clientes de las estaciones participantes de Grupo GEN, accesible mediante la aplicación y los canales oficiales que se informen. Permite consultar puntos, movimientos, premios, novedades y promociones.\n\nTitular y responsable de la aplicación Ruta GEN y organizador comercial del programa: MAZARA GEN S.A., sociedad anónima, CUIT 30-71712174-7. Domicilio fiscal y sede informados: Av. Varela 15, piso 11, departamento A, código postal 1406, Ciudad Autónoma de Buenos Aires, República Argentina. Consultas y reclamos sobre el programa, puntos, canjes y premios: mazara@grupogen.com.ar. Estaciones participantes: consultar https://grupogen.com.ar. El alcance territorial de cada promoción se informa en sus bases particulares.\n\nSoporte técnico de la aplicación: lbcodeworks@gmail.com. Las consultas comerciales y los reclamos por beneficios del programa deben dirigirse al organizador por el correo indicado anteriormente.\n\nRuta GEN es la denominación comercial del programa de fidelización. La titularidad y responsabilidad aquí identificadas corresponden a Mazara, no a la persona o al proveedor que brinda el desarrollo o soporte técnico. Cada sorteo deberá identificar además al organizador legal de esa promoción y al responsable de la entrega de sus premios.\n\nLa publicación y administración de la aplicación desde las cuentas de desarrollador de Mazara requiere los trámites correspondientes ante Apple y Google. Estos términos no modifican por sí solos la titularidad de las cuentas ni transfieren la aplicación en esas plataformas."),
  TermsSectionData(number: "4", title: "Registro, cuenta personal y acceso", content: "La creación de la cuenta es gratuita. Deben informarse datos verdaderos, mantenerse actualizados y protegerse las credenciales de acceso. La cuenta y sus beneficios son personales; no pueden compartirse, venderse ni usarse para acreditar operaciones de otra persona. No se permite crear cuentas duplicadas para obtener beneficios repetidos o eludir las reglas.\n\nEl DNI no es obligatorio para crear la cuenta. Las funciones que exijan identificación o verificación presencial informarán esa condición antes de utilizarlas. La app de clientes está destinada a cuentas con rol de cliente; las cuentas de vendedores operan mediante el sistema de Playa y no están habilitadas para ingresar como clientes."),
  TermsSectionData(number: "5", title: "Identificación y verificación presencial", content: "Para habilitar las operaciones que requieren cuenta verificada, el cliente debe completar su DNI y presentarse ante el personal de una estación participante con su DNI físico o digital. El personal verificará que el documento corresponda al titular de la cuenta y confirmará la identidad.\n\nLa verificación no autoriza a usar documentos, cuentas o códigos QR de terceros. Los datos tratados durante esta operación deben informarse en la política de privacidad. La mera verificación no genera por sí sola un regalo: los beneficios se rigen por la promoción específica que los ofrece."),
  TermsSectionData(number: "6", title: "Acreditación de puntos y máximo por carga", content: "Además del pago mediante App YPF exigido en el apartado 1, los puntos se acreditan por operaciones válidas e identificadas conforme a las equivalencias, estaciones y promociones vigentes informadas al cliente. Cuando exista un mínimo de litros u otra condición para acreditar puntos, deberá comunicarse antes de la operación. Una carga solo puede acreditarse una vez y a una única cuenta.\n\nPor cada carga de combustible se acreditan como máximo 70 puntos finales. Primero se aplica a los litros validados el multiplicador vigente, se redondea al entero más cercano y luego se aplica el límite de 70 puntos. Por ejemplo: con equivalencia 1×, una carga de 80 litros acredita 70 puntos; con equivalencia 2×, una carga de 40 litros también acredita 70 puntos, siempre que se cumpla el mínimo exigible.\n\nEl límite es de puntos, no de litros que pueden cargarse. El despacho conserva su volumen real para el historial, el control y los rankings que utilicen litros de operaciones válidas. No se permite fraccionar artificialmente un mismo despacho para eludir el límite. Los bonos por visitas y otros beneficios distintos de la acreditación de una carga se rigen por sus propias condiciones publicadas."),
  TermsSectionData(number: "7", title: "Multiplicadores y promociones de acumulación", content: "Los factores y períodos promocionales se informan en la app o en los canales del programa. Si coinciden varios multiplicadores aplicables a una carga, se utiliza el mayor de ellos; no se multiplican ni suman entre sí. El máximo final de 70 puntos por carga se mantiene también durante las promociones.\n\nLos cambios de equivalencia o del límite se aplican a operaciones futuras desde la vigencia previamente informada. No recalculan retroactivamente las acreditaciones válidas anteriores ni habilitan a acreditar otra vez una operación ya registrada."),
  TermsSectionData(number: "8", title: "Vigencia anual de los puntos", content: "Los puntos acreditados durante cada año calendario tienen vigencia hasta el 31 de diciembre de ese año, inclusive, a las 23:59:59, hora de la República Argentina. Desde las 00:00 del 1 de enero siguiente, los puntos no utilizados de ese período caducan y no se trasladan como saldo para canjes al nuevo año.\n\nEl vencimiento no elimina el historial de operaciones ni afecta los puntos que se acrediten durante el nuevo año. Tampoco altera por sí solo los registros de participación de un sorteo cuyo período publicado atraviese el cambio de año. Los premios ya asignados tienen la vigencia indicada en su propia promoción o comprobante.\n\nEl organizador deberá informar de forma clara esta vigencia y atender los reclamos por vencimientos o saldos incorrectos. La falta de actualización visual o una falla técnica no autoriza a desconocer los derechos que correspondan al usuario."),
  TermsSectionData(number: "9", title: "Naturaleza y uso de los puntos", content: "Los puntos son unidades del programa para acceder a los beneficios publicados. No son moneda de curso legal, no generan intereses y no pueden venderse, transferirse a otras cuentas ni canjearse por efectivo.\n\nEstas características no limitan los derechos del consumidor a reclamar por operaciones incorrectas, incumplimientos, devoluciones o compensaciones que correspondan conforme a la normativa aplicable."),
  TermsSectionData(number: "10", title: "Canjes por puntos", content: "Antes de confirmar un canje, el cliente podrá conocer el premio, su costo en puntos, las condiciones de retiro y, cuando corresponda, la disponibilidad o limitación de stock previamente informada. La confirmación debe corresponder a un saldo suficiente y a un premio disponible.\n\nEl canje confirmado descuenta los puntos indicados y queda registrado con su fecha y estación. El organizador debe respetar las condiciones ofrecidas y los canjes confirmados. Una falta de stock posterior no autoriza a desconocer un beneficio ya confirmado ni a sustituirlo unilateralmente por otro de menor valor o características."),
  TermsSectionData(number: "11", title: "Regalos y beneficios promocionales", content: "Los regalos asignados sin costo en puntos se muestran como Gratis. Premio recibido significa que el beneficio fue asignado y, mientras esté disponible y vigente, puede canjearse con su QR. Regalo canjeado significa que ya fue entregado y debe figurar con su fecha, hora y estación de canje.\n\nCada beneficio tiene las condiciones de vigencia, cantidad y frecuencia informadas al asignarlo. El regalo por primera carga solo corresponde cuando la promoción está activa y se cumplen sus requisitos: cuenta verificada, primera carga válida con puntos acreditados y ausencia de una entrega anterior del mismo beneficio o de un beneficio equivalente que impida repetirlo. No se genera por verificar el DNI ni por repetir una carga.\n\nLas promociones por visitas, campañas y demás regalos pueden tener reglas diferentes. Sus condiciones particulares deben comunicarse antes de participar y no pueden modificarse retroactivamente en perjuicio de beneficios ya asignados."),
  TermsSectionData(number: "12", title: "Sorteos: información en la app y bases particulares", content: "Los sorteos no se realizan dentro de la aplicación Ruta GEN. La app puede mostrar sorteos activos, fechas, condiciones, rankings y resultados, pero no ejecuta el mecanismo de selección de ganadores. La organización, realización y comunicación se efectúan por los canales oficiales identificados en las bases particulares, que pueden incluir redes sociales.\n\nPara determinar las participaciones o una preselección, el organizador puede utilizar datos de clientes y operaciones registrados en la base de datos de Ruta GEN, exclusivamente conforme a las bases informadas y a la política de privacidad. La selección efectiva de ganadores se realiza fuera de la app, mediante el procedimiento y en la fecha indicados para esa promoción. Realizarla o comunicarla por redes sociales no elimina las obligaciones legales ni las autorizaciones que correspondan.\n\nCada sorteo se rige por sus bases y condiciones particulares, publicadas de forma accesible antes de su inicio. No existe un cupo general de 20, 50 u otra cantidad aplicable a todos los sorteos. Cada promoción debe indicar su número de finalistas, período de participación, premio y forma de adjudicación.\n\nCuando las bases prevean una preselección por ranking, deberán precisar la métrica utilizada, las operaciones que computan, la fecha y hora de corte, el tratamiento de empates y la forma de participación sin compra que corresponda. Los rankings mostrados durante el período son provisorios y están sujetos al cierre y a las validaciones objetivas previstas en esas bases.\n\nEjemplo ilustrativo: si una promoción anuncia 50 finalistas, se determina el listado de las primeras 50 cuentas elegibles conforme a sus bases y luego se realiza la selección al azar entre esos finalistas. Integrar el ranking o quedar primero no significa ganar automáticamente la moto, la bicicleta u otro premio. Si hay menos participantes elegibles que cupos, se consideran los elegibles existentes, conforme a lo informado para esa promoción.\n\nEn un sorteo de un único premio, con una participación igual por finalista y 50 finalistas efectivos, la probabilidad individual de adjudicación es 1 en 50. La cantidad efectiva de participantes y las probabilidades aplicables deberán informarse para cada promoción. El saldo disponible para canjes no debe confundirse con la métrica de un ranking: una promoción que use litros debe explicarlo expresamente."),
  TermsSectionData(number: "13", title: "Participación gratuita en promociones con azar", content: "Las promociones con intervención del azar deben ajustarse a la normativa aplicable y no pueden condicionar la participación, total o parcialmente, a realizar una compra o contratar un servicio. Sus bases deberán describir una vía real, gratuita, accesible y efectivamente habilitada para participar sin compra, con condiciones que no vacíen de contenido esa posibilidad.\n\nLa leyenda Sin obligación de compra no reemplaza la implementación de ese mecanismo. La promoción deberá informar cómo participar, dónde, durante qué fechas y horarios y cómo se integra esa participación a la selección y adjudicación de premios. No se cobra un precio de inscripción ni se venden participaciones mediante Ruta GEN."),
  TermsSectionData(number: "14", title: "Información que debe publicar cada sorteo", content: "Las bases de cada promoción deben identificar al organizador y permitir conocer antes de participar: alcance geográfico; fechas y horarios de inicio, cierre y sorteo; requisitos y exclusiones; modo de participación gratuita sin compra; cupo y selección de finalistas, si corresponde; desempates; procedimiento de selección de titulares y suplentes; cantidad y descripción de premios; probabilidades o su forma de cálculo; comunicación de resultados; forma y plazo para acreditar identidad y retirar el premio; gastos a cargo de cada parte y destino de los premios no adjudicados.\n\nPara una moto u otro bien registrable deberán detallarse, además, las características del vehículo, condiciones de entrega y quién asume los trámites, impuestos, patentamiento, traslado y demás gastos aplicables. No podrán exigirse gastos que no hayan sido informados en las bases. Los términos generales de la app no reemplazan esas bases ni las autorizaciones que correspondan según la jurisdicción."),
  TermsSectionData(number: "15", title: "Adjudicación, resultados y entrega de premios", content: "La selección se realiza mediante el mecanismo anunciado en las bases. El organizador deberá conservar los registros de participantes, selección, ganadores y entrega que resulten exigibles. La validación de identidad debe limitarse a comprobar requisitos publicados y no habilita exclusiones arbitrarias.\n\nLas bases deben indicar los medios oficiales de comunicación y los plazos razonables para responder y retirar el premio. La notificación push es un canal complementario: una falla en su entrega no reemplaza las obligaciones de comunicación asumidas por el organizador. La publicación de resultados deberá limitar los datos personales expuestos a los necesarios.\n\nLos suplentes, la falta de respuesta y los premios no adjudicados se tratan conforme al procedimiento anunciado previamente. No se presumirá la pérdida del premio por condiciones no informadas o por fallas atribuibles al organizador.\n\nApple no patrocina, administra ni participa en los sorteos o concursos ofrecidos en esta aplicación."),
  TermsSectionData(number: "16", title: "QR, seguridad y prevención de uso indebido", content: "El QR de la cuenta identifica al cliente y no debe compartirse con terceros. El QR de un regalo identifica ese beneficio y solo permite su canje una vez, mientras esté disponible y vigente. Los códigos pueden renovarse o invalidarse por uso, vencimiento o razones justificadas de seguridad.\n\nNo se permite acreditar despachos de terceros, utilizar identidades ajenas, alterar comprobantes, reutilizar operaciones ni facilitar a empleados o terceros el acceso a la cuenta para obtener puntos o premios indebidos. El personal de Playa y Tienda debe utilizar sus accesos de trabajo y no puede eludir sus restricciones mediante cuentas ajenas.\n\nLa huella o Face ID se procesa mediante los mecanismos del dispositivo. Ruta GEN no recibe ni almacena imágenes de huellas o rostros; utiliza la autenticación del dispositivo para autorizar el acceso a las credenciales protegidas."),
  TermsSectionData(number: "17", title: "Correcciones, revisiones y reclamos", content: "El organizador podrá revisar duplicaciones, errores y operaciones con indicios objetivos de irregularidad. Las correcciones de puntos deberán estar justificadas y quedar registradas con motivo, fecha y hora. No podrán eliminarse acreditaciones válidas de forma arbitraria.\n\nCuando una revisión afecte el saldo, una participación o un premio, el usuario podrá solicitar información y presentar comprobantes por el canal de reclamos identificado en estos términos. Una medida preventiva de seguridad debe ser proporcional y permitir su revisión. La suspensión de una cuenta no implica por sí sola una renuncia a derechos ni la liberación de las obligaciones del organizador."),
  TermsSectionData(number: "18", title: "Datos personales y comunicaciones", content: "Los datos de la cuenta y de sus operaciones se utilizan para administrar el programa, identificar al titular cuando corresponda, acreditar puntos, registrar canjes, prevenir irregularidades, atender reclamos y gestionar promociones. MAZARA GEN S.A. es la entidad responsable del tratamiento de datos personales del programa. La política de privacidad debe detallar los datos tratados, finalidades, destinatarios, conservación, medidas de seguridad y vías para ejercer derechos; estos términos no sustituyen esa información.\n\nEl usuario puede ejercer los derechos de acceso, rectificación, actualización y supresión conforme a la Ley 25.326 por el canal informado. Las comunicaciones comerciales y el eventual uso publicitario de imagen o testimonios deberán contar con la base legal y las autorizaciones específicas que correspondan; aceptar estos términos no constituye una autorización ilimitada para esos usos.\n\nLa publicación de ganadores o rankings debe limitar los datos personales y respetar lo informado para la promoción. El usuario puede gestionar los permisos de notificaciones y biometría desde las opciones del dispositivo y de la app."),
  TermsSectionData(number: "19", title: "Baja de cuenta y funcionamiento del servicio", content: "La app permite solicitar la eliminación de la cuenta desde las opciones de cuenta. Antes de confirmar deben informarse sus efectos sobre el acceso al programa, los datos y beneficios pendientes. La baja se realiza sin perjuicio de los derechos ya adquiridos y de los registros que deban conservarse por obligaciones legales, que deberán tratarse de forma adecuada.\n\nPuede haber interrupciones por mantenimiento o problemas de conectividad. El organizador deberá brindar un canal para informar operaciones no reflejadas y atender las soluciones que correspondan. Una falla técnica no habilita a desconocer automáticamente cargas válidas, canjes confirmados o premios adjudicados."),
  TermsSectionData(number: "20", title: "Actualizaciones del programa y de estos términos", content: "Las reglas, equivalencias y condiciones pueden actualizarse para operaciones futuras, con información clara y previa sobre su contenido y entrada en vigencia. Los cambios relevantes deberán comunicarse de forma destacada; una fecha de aceptación antigua no acredita por sí sola la aceptación de una versión posterior.\n\nNo se alterarán retroactivamente en perjuicio del usuario las condiciones de participaciones iniciadas, acreditaciones válidas o premios adjudicados, sin perjuicio de los vencimientos ya informados y de las correcciones justificadas de errores. El cierre de una promoción o del programa debe respetar las obligaciones asumidas y los derechos que correspondan a sus usuarios."),
  TermsSectionData(number: "21", title: "Normativa aplicable y derechos del consumidor", content: "El programa se encuentra sujeto a las normas argentinas aplicables, incluyendo defensa del consumidor, lealtad comercial, protección de datos personales y los regímenes específicos que correspondan a cada promoción y jurisdicción. Las bases particulares complementan estos términos dentro de esos límites.\n\nNinguna cláusula implica renuncia a garantías legales, limita derechos irrenunciables ni impone una jurisdicción exclusiva que prive al consumidor de los tribunales o autoridades que le correspondan. Las dudas se resolverán conforme a la normativa de protección al consumidor. El usuario puede acudir al organizador, a la autoridad de defensa del consumidor competente y, para sus datos personales, a la Agencia de Acceso a la Información Pública."),
];
